import numpy as np

def make_obs(agent=None, ch1=None, ch2=None, ch3=None, ch4=None):
    x = np.zeros((10,10,5), dtype=np.float32)
    x[0,:,3]=1; x[9,:,3]=1; x[:,0,3]=1; x[:,9,3]=1
    if agent is not None:
        x[agent[0],agent[1],0]=1
    for ch, pts in [(1,ch1),(2,ch2),(3,ch3),(4,ch4)]:
        if pts is not None:
            for p in pts:
                x[p[0],p[1],ch]=1
    return x.flatten()

agent = (5,5)
obs_list = []
labels = []

obs_list.append(make_obs(agent=agent))
labels.append(('agent', None, None))

offsets = []
for dr in range(-3,4):
    for dc in range(-3,4):
        if dr==0 and dc==0: continue
        r, c = agent[0]+dr, agent[1]+dc
        if 1<=r<=8 and 1<=c<=8:
            offsets.append((dr,dc,r,c))

for ch in [1,2,3]:
    for dr,dc,r,c in offsets:
        pts = [(r,c)]
        if ch==1: o = make_obs(agent=agent, ch1=pts)
        elif ch==2: o = make_obs(agent=agent, ch2=pts)
        else: o = make_obs(agent=agent, ch3=pts)
        obs_list.append(o)
        labels.append((f'ch{ch}', (dr,dc), (r,c)))

combos = [
    ('reward_right', dict(ch2=[(5,7)])),
    ('reward_left', dict(ch2=[(5,3)])),
    ('reward_up', dict(ch2=[(3,5)])),
    ('reward_down', dict(ch2=[(7,5)])),
    ('moving_right', dict(ch1=[(5,7)])),
    ('moving_left', dict(ch1=[(5,3)])),
    ('moving_up', dict(ch1=[(3,5)])),
    ('moving_down', dict(ch1=[(7,5)])),
    ('obstacle_right', dict(ch3=[(5,7)])),
    ('obstacle_left', dict(ch3=[(5,3)])),
    ('reward_right_moving_left', dict(ch2=[(5,7)], ch1=[(5,3)])),
    ('reward_right_obstacle_left', dict(ch2=[(5,7)], ch3=[(5,3)])),
]
for name, kw in combos:
    obs_list.append(make_obs(agent=agent, **kw))
    labels.append((name, None, None))

X = np.array(obs_list, dtype=np.float32)
logits = forward(X)
base = logits[0]
print("agent_only logits:", np.round(base,2))
print("actions: 0=noop,1=up,2=down,3=left,4=right")

print("\n=== combined cases ===")
combo_names = [c[0] for c in combos]
for idx, (name, _, _) in enumerate(labels):
    if name in combo_names:
        delta = logits[idx] - base
        print(f"{name:30s} logits: {np.round(logits[idx],2)} delta: {np.round(delta,2)}")

for ch in [1,2,3]:
    grid_toward = np.full((7,7), np.nan)
    grid_away = np.full((7,7), np.nan)
    for idx, (lab, off, pos) in enumerate(labels):
        if lab != f'ch{ch}': continue
        dr, dc = off
        delta = logits[idx] - base
        toward_actions = []
        away_actions = []
        if dr < 0: toward_actions.append(1); away_actions.append(2)
        elif dr > 0: toward_actions.append(2); away_actions.append(1)
        if dc < 0: toward_actions.append(3); away_actions.append(4)
        elif dc > 0: toward_actions.append(4); away_actions.append(3)
        if toward_actions:
            grid_toward[dr+3, dc+3] = np.mean([delta[a] for a in toward_actions])
            grid_away[dr+3, dc+3] = np.mean([delta[a] for a in away_actions])
    print(f"\n=== channel {ch} delta toward object (positive=move toward) ===")
    print("rows dr=-3..3, cols dc=-3..3")
    for i in range(7):
        row = []
        for j in range(7):
            if np.isnan(grid_toward[i,j]):
                row.append("   .  ")
            else:
                row.append(f"{grid_toward[i,j]:+5.1f}")
        print(" ".join(row))
    print(f"=== channel {ch} delta away from object ===")
    for i in range(7):
        row = []
        for j in range(7):
            if np.isnan(grid_away[i,j]):
                row.append("   .  ")
            else:
                row.append(f"{grid_away[i,j]:+5.1f}")
        print(" ".join(row))

import numpy as np

def make_input(agent=None):
    x = np.zeros(500)
    # wall border in channel 3
    for r in range(10):
        for c in range(10):
            if r == 0 or r == 9 or c == 0 or c == 9:
                x[(r*10+c)*5 + 3] = 1
    if agent is not None:
        r, c = agent
        x[(r*10+c)*5 + 0] = 1
    return x

cases = [None, (1,4), (1,5), (8,4), (6,4)]
X = np.array([make_input(a) for a in cases])
logits = forward(X)
base = logits[0]
for a, l in zip(cases, logits):
    label = "empty" if a is None else f"agent{a}"
    delta = l - base
    print(f"{label:12s} logits={np.round(l,3)} delta={np.round(delta,3)} argmax={np.argmax(l)}")
